INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das deklarative Paradigma darauf ausgelegt, den Ablauf Schritt für Schritt zu steuern?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus liegt auf dem Was, nicht dem Wie"}, {"text": "Ja", "correct": false, "because": "Das wäre imperativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sprache ist typisch für dieses Programmierkonzept?', 3, '[{"text": "SQL", "correct": true, "because": "Beschreibt Ergebnisse, nicht Schritte"}, {"text": "Java", "correct": false, "because": "Imperativ ausgerichtet"}, {"text": "C++", "correct": false, "because": "Prozedural und objektorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet mir dieses Paradigma?', 5, '[{"text": "Lesbarkeit", "correct": true, "because": "Klarere Absichtserklärung"}, {"text": "Abstraktion", "correct": true, "because": "Verbirgt Implementierung"}, {"text": "Maximale Kontrolle", "correct": false, "because": "Weniger detailliert"}, {"text": "Höhere Geschwindigkeit", "correct": false, "because": "Optimierung liegt beim Compiler"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Deklarativ beschreibt das Ziel. b) Es steuert die Ausführung direkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist imperativ"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich deklarativ programmiere?', 4, '[{"text": "Ergebnisdefinition", "correct": false, "because": "Kern des Ansatzes"}, {"text": "Datenstruktur", "correct": false, "because": "Muss oft spezifiziert werden"}, {"text": "Ausführungsreihenfolge", "correct": true, "because": "Liegt beim System"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob HTML deklarativ ist?', 2, '[{"text": "Ja", "correct": true, "because": "Beschreibt Struktur, nicht Logik"}, {"text": "Nein", "correct": false, "because": "Nicht prozedural"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit diesem Ansatz?', 3, '[{"text": "Beschreibung des Ergebnisses", "correct": true, "because": "Fokus auf Was statt Wie"}, {"text": "Detaillierte Ablaufsteuerung", "correct": false, "because": "Imperativer Ansatz"}, {"text": "Maximale Performance", "correct": false, "because": "Nicht primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften passen zu diesem Paradigma?', 5, '[{"text": "Abstraktion", "correct": true, "because": "Verbirgt Details"}, {"text": "Wartbarkeit", "correct": true, "because": "Klarere Struktur"}, {"text": "Schleifensteuerung", "correct": false, "because": "Imperativ"}, {"text": "Befehlssequenzen", "correct": false, "because": "Prozedural"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Deklarativ ist einfacher zu lesen. b) Es ist immer schneller. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit hängt vom System ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich so programmiere?', 4, '[{"text": "Zielbeschreibung", "correct": false, "because": "Kern des Ansatzes"}, {"text": "Datenquellen", "correct": false, "because": "Oft notwendig"}, {"text": "Schritt-für-Schritt-Anweisungen", "correct": true, "because": "System übernimmt das"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Prolog ein Beispiel dafür?', 2, '[{"text": "Ja", "correct": true, "because": "Logikbasierte Deklaration"}, {"text": "Nein", "correct": false, "because": "Es ist deklarativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sprachen nutzen diesen Ansatz?', 4, '[{"text": "SQL", "correct": true, "because": "Ergebnisse definieren"}, {"text": "Haskell", "correct": true, "because": "Funktional und deklarativ"}, {"text": "Python", "correct": false, "because": "Imperativ möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass deklaratives Programmieren keine Schleifen braucht. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Abstraktion ersetzt Schleifen"}, {"text": "Nein", "correct": false, "because": "Schleifen sind oft implizit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei diesem Ansatz?', 3, '[{"text": "Klarheit des Ziels", "correct": true, "because": "Was statt Wie im Fokus"}, {"text": "Manuelle Optimierung", "correct": false, "because": "System übernimmt das"}, {"text": "Detaillierte Abläufe", "correct": false, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es abstrahiert Implementierung. b) Es ist immer objektorientiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Paradigma-unabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen diesen Ansatz nützlich?', 5, '[{"text": "Weniger Fehler", "correct": true, "because": "Weniger manuelle Steuerung"}, {"text": "Einfachere Wartung", "correct": true, "because": "Klarere Absicht"}, {"text": "Maximale Kontrolle", "correct": false, "because": "Abstraktion reduziert Kontrolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei diesem Paradigma unwichtig?', 3, '[{"text": "Ergebnisdefinition", "correct": false, "because": "Kern des Ansatzes"}, {"text": "Datenstruktur", "correct": false, "because": "Oft relevant"}, {"text": "Ablaufsteuerung", "correct": true, "because": "Systemabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erfordert es mehr Hardwareleistung?', 3, '[{"text": "Nein", "correct": true, "because": "Leistung hängt von Optimierung ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob CSS dazu gehört?', 2, '[{"text": "Ja", "correct": true, "because": "Beschreibt Darstellung"}, {"text": "Nein", "correct": false, "because": "Es ist deklarativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel passt zu diesem Ansatz?', 4, '[{"text": "Eine Datenbankabfrage", "correct": true, "because": "Ergebnis definiert"}, {"text": "Eine for-Schleife", "correct": false, "because": "Imperative Steuerung"}, {"text": "Ein if-Statement", "correct": false, "because": "Prozedurale Logik"}]');
